mapper.select:
SELECT 

FROM equipment_resource
WHERE 1=1

    AND planning_id = #{param.planningId}


    AND equipment_name LIKE CONCAT('%', #{param.equipmentName}, '%')


    AND equipment_type = #{param.equipmentType}


    AND equipment_model LIKE CONCAT('%', #{param.equipmentModel}, '%')


    AND allocation_status = #{param.allocationStatus}


    AND equipment_status = #{param.equipmentStatus}


    AND supplier_name LIKE CONCAT('%', #{param.supplierName}, '%')


    AND manager_id = #{param.managerId}


    AND manager_name LIKE CONCAT('%', #{param.managerName}, '%')


    AND budgeted_cost >= #{param.minBudgetedCost}


    AND budgeted_cost <= #{param.maxBudgetedCost}


    AND actual_cost >= #{param.minActualCost}


    AND actual_cost <= #{param.maxActualCost}


    AND purchase_date >= #{param.purchaseStartDate}


    AND purchase_date <= #{param.purchaseEndDate}


    AND delivery_date >= #{param.deliveryStartDate}


    AND delivery_date <= #{param.deliveryEndDate}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}


    AND create_by = #{param.createBy}


    AND (equipment_name LIKE CONCAT('%', #{param.keyword}, '%')
         OR equipment_model LIKE CONCAT('%', #{param.keyword}, '%')
         OR supplier_name LIKE CONCAT('%', #{param.keyword}, '%')
         OR manager_name LIKE CONCAT('%', #{param.keyword}, '%')
         OR remarks LIKE CONCAT('%', #{param.keyword}, '%'))

ORDER BY create_time DESC, id DESC

SELECT COALESCE(SUM(budgeted_cost), 0)
FROM equipment_resource
WHERE planning_id = #{planningId}

SELECT COALESCE(SUM(actual_cost), 0)
FROM equipment_resource
WHERE planning_id = #{planningId}

SELECT COALESCE(SUM(required_quantity), 0)
FROM equipment_resource
WHERE equipment_type = #{equipmentType}

SELECT COALESCE(SUM(allocated_quantity), 0)
FROM equipment_resource
WHERE equipment_type = #{equipmentType}

SELECT COUNT(*)
FROM equipment_resource
WHERE allocation_status = #{allocationStatus}

SELECT COUNT(*)
FROM equipment_resource
WHERE equipment_status = #{equipmentStatus}

